import os
os.environ.setdefault("TF_CPP_MIN_LOG_LEVEL", "2")
import numpy as np
import tensorflow as tf
from tensorflow.keras import layers

# %% ../nbs/01_layers.ipynb #08aed794
@tf.keras.utils.register_keras_serializable()
class ElementWiseMultiplyLayer(layers.Layer):
    """Custom layer for element-wise multiplication with learnable weights."""

    def __init__(self, units, weight_initializer, **kwargs):
        super().__init__(**kwargs)
        self.units = units
        self.weight_initializer = weight_initializer

    def build(self, input_shape):
        self.output_weights = self.add_weight(
            name='output_weights',
            shape=(self.units,),
            initializer=self.weight_initializer,
            trainable=True
        )
        super().build(input_shape)

    def call(self, inputs):
        return inputs * self.output_weights

    def get_config(self):
        config = super().get_config()
        config.update({
            'units': self.units,
            'weight_initializer': tf.keras.utils.serialize_keras_object(self.weight_initializer),
        })
        return config

    @classmethod
    def from_config(cls, config):
        config['weight_initializer'] = tf.keras.utils.deserialize_keras_object(
            config['weight_initializer']
        )
        return cls(**config)

